<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {RouterLink} from 'vue-router';
import {Files,Inbox,ClipboardCheck,Building2,ArrowUpLeft,CalendarDays,ChartNoAxesCombined,ShieldCheck,RefreshCw} from '@lucide/vue';
import {api} from '../../lib/api';
import type {DashboardStats,ReportRecord} from '../../../shared/types';
import {categoryLabel} from '../../../shared/catalog';
import {displayDate,messageOf} from './helpers';
import AdminState from './AdminState.vue';
import StatusBadge from './StatusBadge.vue';
const stats=ref<DashboardStats|null>(null),reports=ref<ReportRecord[]>([]),loading=ref(true),error=ref('');
const colors=['#497fe3','#53b5ad','#e4b05c','#9b83c5','#82b6ce','#d58ca7','#7c9bb4','#c6b367','#91b97a','#bb96cd','#a7b5c6'];
const categoryTotal=computed(()=>stats.value?.byCategory.reduce((sum,x)=>sum+x.count,0)||0);
const donut=computed(()=>{let total=0;return `conic-gradient(${(stats.value?.byCategory||[]).map((item,i)=>{const start=total;total+=item.count/Math.max(categoryTotal.value,1)*100;return `${colors[i%colors.length]} ${start}% ${total}%`;}).join(',')||'#edf2f7 0% 100%'})`;});
const maxMonth=computed(()=>Math.max(1,...(stats.value?.monthly.map(x=>x.count)||[])));
async function load(){loading.value=true;error.value='';try{const [s,r]=await Promise.all([api<DashboardStats>('/api/admin/stats'),api<{reports:ReportRecord[]}>('/api/admin/reports?page=1&pageSize=5&sort=newest')]);stats.value=s;reports.value=r.reports;}catch(e){error.value=messageOf(e);}finally{loading.value=false;}}
onMounted(load);
</script>
<template><div class="admin-page-heading"><div><span class="admin-eyebrow">כל הדיווחים. תמונה אחת.</span><h1>תמונת המצב של הארגון</h1><p>מידע עדכני מתוך הדיווחים שנמסרו למערכת.</p></div><button class="btn btn-secondary" :disabled="loading" @click="load"><RefreshCw :size="16"/>רענון נתונים</button></div>
<div v-if="error" class="admin-error" role="alert">{{error}}</div><AdminState v-if="loading" loading/>
<template v-else-if="stats"><div class="admin-stat-grid"><section v-for="card in [{label:'דיווחים שהתקבלו',value:stats.total,icon:Files,color:'blue',hint:'כל הדיווחים במערכת'},{label:'דיווחים חדשים',value:stats.newReports,icon:Inbox,color:'teal',hint:'ממתינים לבדיקה ראשונית'},{label:'דיווחים בבדיקה',value:stats.inReview,icon:ClipboardCheck,color:'amber',hint:'נמצאים בתהליך הבדיקה'},{label:'חברות וגופים',value:stats.companyCount,icon:Building2,color:'purple',hint:'חברות המוזכרות בדיווחים'}]" :key="card.label" class="stat-card"><div class="stat-card-top">{{card.label}}<span :class="['stat-icon','stat-icon-'+card.color]"><component :is="card.icon" :size="19"/></span></div><strong>{{card.value.toLocaleString('he-IL')}}</strong><small>{{card.hint}}</small></section></div>
<div class="admin-dashboard-charts"><section class="admin-panel"><header class="admin-panel-header"><div><h2><CalendarDays :size="18"/>דיווחים לאורך זמן</h2><p>מספר הדיווחים שנקלטו בכל חודש</p></div><span class="admin-chart-key"><i/>דיווחים</span></header><div v-if="stats.monthly.length" class="admin-bar-chart" role="img" :aria-label="stats.monthly.map(x=>x.month+': '+x.count+' דיווחים').join(', ')"><div class="admin-chart-grid"><span>{{maxMonth}}</span><span>{{Math.floor(maxMonth/2)}}</span><span>0</span></div><div class="admin-bars"><div v-for="(month,index) in stats.monthly" :key="month.month" class="admin-bar-column"><span class="admin-bar-value">{{month.count}}</span><div class="admin-bar-track"><div :class="['admin-bar',{'bar-latest':index===stats.monthly.length-1}]" :style="{height:(month.count/maxMonth*100)+'%'}"/></div><span class="admin-bar-label">{{month.month}}</span></div></div></div><AdminState v-else title="אין עדיין דיווחים"/></section>
<section class="admin-panel"><header class="admin-panel-header"><div><h2><ChartNoAxesCombined :size="18"/>על מה מדווחים?</h2><p>התפלגות לפי קטגוריה ראשית</p></div></header><div class="admin-category-chart"><div class="admin-donut" :style="{background:donut}" aria-hidden="true"><div><strong>{{stats.total}}</strong><span>דיווחים</span></div></div><div class="admin-donut-legend"><div v-for="(item,index) in stats.byCategory" :key="item.category"><i :style="{background:colors[index%colors.length]}"/><span>{{categoryLabel(item.category)}}</span><strong>{{item.count}}</strong></div><span v-if="!stats.byCategory.length">אין עדיין קטגוריות להצגה</span></div></div></section></div>
<div class="admin-dashboard-bottom"><section class="admin-panel"><header class="admin-panel-header"><h2>דיווחים אחרונים</h2><RouterLink to="/admin/reports" class="admin-text-link">לכל הדיווחים<ArrowUpLeft :size="14"/></RouterLink></header><div v-if="reports.length" class="table-wrap"><table class="data-table"><thead><tr><th>מספר דיווח</th><th>חברה</th><th>תאריך</th><th>סטטוס</th></tr></thead><tbody><tr v-for="report in reports" :key="report.id"><td><RouterLink :to="'/admin/reports/'+report.id" class="admin-report-reference">{{report.publicReference}}</RouterLink><small>{{categoryLabel(report.primaryCategory)}}</small></td><td>{{report.companies.map(x=>x.name).join(', ')}}</td><td>{{displayDate(report.createdAt)}}</td><td><StatusBadge :status="report.status"/></td></tr></tbody></table></div><AdminState v-else title="עדיין לא התקבלו דיווחים"/></section>
<section class="admin-panel"><header class="admin-panel-header"><h2>חברות המוזכרות בדיווחים</h2><Building2 :size="19"/></header><div class="admin-company-bars"><RouterLink v-for="(company,index) in stats.byCompany.slice(0,5)" :key="company.name" :to="{path:'/admin/reports',query:{company:company.name}}"><div><span><i>{{index+1}}</i>{{company.name}}</span><strong>{{company.count}}</strong></div><div class="admin-mini-bar"><span :style="{width:(company.count/Math.max(1,...stats.byCompany.map(x=>x.count))*100)+'%'}"/></div></RouterLink></div><AdminState v-if="!stats.byCompany.length" title="אין חברות להצגה"/><div class="admin-panel-bottom">מספר הדיווחים אינו מעיד על קיומה של הפרה.</div></section></div>
<div class="admin-workspace-note"><ShieldCheck :size="24"/><div><strong>הדיווח הוא תחילתה של בדיקה</strong><span>הנתונים מבוססים על דברי הפונים. התאמות ודפוסים מחייבים בדיקה אנושית.</span></div><RouterLink to="/admin/patterns">לקבוצות התאמה<ArrowUpLeft :size="15"/></RouterLink></div></template></template>
